import{_ as t,o as i,c as o,ae as a}from"./chunks/framework.DPZ3sAUK.js";const g=JSON.parse('{"title":"neuron-js: Pluggable Execution Runtime","description":"","frontmatter":{},"headers":[],"relativePath":"overview.md","filePath":"overview.md"}'),n={name:"overview.md"};function s(r,e,l,c,u,d){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="neuron-js-pluggable-execution-runtime" tabindex="-1">neuron-js: Pluggable Execution Runtime <a class="header-anchor" href="#neuron-js-pluggable-execution-runtime" aria-label="Permalink to &quot;neuron-js: Pluggable Execution Runtime&quot;">​</a></h1><p><code>neuron-js</code> is a lightweight, extensible, and JSON-serializable execution engine for JavaScript. It allows developers to define complex logic flows (functional scripts) that can be stored in a database, transmitted over the wire, and executed consistently in both Node.js and browser environments.</p><h2 id="the-problem" tabindex="-1">The Problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The Problem&quot;">​</a></h2><p>Hardcoding business logic often leads to rigid systems that are difficult to update without a full deployment. Workflow engines are often heavy, difficult to integrate, or use proprietary formats.</p><h2 id="the-solution" tabindex="-1">The Solution <a class="header-anchor" href="#the-solution" aria-label="Permalink to &quot;The Solution&quot;">​</a></h2><p><code>neuron-js</code> provides a registry-based approach to execution logic:</p><ul><li><strong>Neuron (Registry)</strong>: Stores the definitions of what is possible (Actions, Conditions, Rules, Parameters).</li><li><strong>Synapse (Engine)</strong>: Executes specific scripts by coordinating these definitions in a logical flow.</li></ul><p>By keeping the script format strictly serializable (JSON), <code>neuron-js</code> enables:</p><ul><li><strong>Dynamic Logic</strong>: Change business rules at runtime without redeploying code.</li><li><strong>Portability</strong>: The same logic can run on a backend server or in a client&#39;s browser.</li><li><strong>Extensibility</strong>: Easily add new capabilities by implementing simple Action or Condition interfaces.</li></ul><h2 id="release-classification" tabindex="-1">Release Classification <a class="header-anchor" href="#release-classification" aria-label="Permalink to &quot;Release Classification&quot;">​</a></h2><p>The <code>0.4.0</code> release is a <strong>minor capability release</strong>, not a major breaking change.</p><p>It expands the documented public API, adds extension base classes, makes missing <code>options</code> objects safe at runtime, and cleans package output. Existing JSON script behavior remains compatible; the release gives consumers more stable imports and clearer plugin ergonomics.</p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>JSON Serializable</strong>: Logic is data.</li><li><strong>Shared Context</strong>: State is managed and passed through the execution chain.</li><li><strong>Logical Grouping</strong>: Complex AND/OR condition logic is supported out of the box.</li><li><strong>Lifecycle Hooks</strong>: Monitor and react to every step of the execution.</li><li><strong>Type Safe</strong>: Built with TypeScript for a robust developer experience.</li></ul>',14)])])}const h=t(n,[["render",s]]);export{g as __pageData,h as default};
